const GREETINGS: Record<string, (name: string) => string> = {
  en: (name) => `Hello, ${name}!`,
  es: (name) => `¡Hola, ${name}!`,
};

const DEFAULT_LOCALE = 'en';

export function greet(name: string = 'world', locale: string = DEFAULT_LOCALE): string {
  const format = Object.hasOwn(GREETINGS, locale)
    ? GREETINGS[locale]
    : GREETINGS[DEFAULT_LOCALE];
  return format(name);
}
===TEST===
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { greet } from './greet.ts';

test('greets the world by default', () => assert.equal(greet(), 'Hello, world!'));
test('greets a named person', () => assert.equal(greet('Shurik'), 'Hello, Shurik!'));

test('greets in English when locale is "en"', () => {
  assert.equal(greet('Shurik', 'en'), 'Hello, Shurik!');
  assert.equal(greet(undefined, 'en'), 'Hello, world!');
});

test('greets in Spanish when locale is "es"', () => {
  assert.equal(greet('Shurik', 'es'), '¡Hola, Shurik!');
  assert.equal(greet('Mundo', 'es'), '¡Hola, Mundo!');
});

test('falls back to English for an unknown locale', () => {
  assert.equal(greet('Shurik', 'fr'), 'Hello, Shurik!');
  assert.equal(greet('Shurik', 'ES'), 'Hello, Shurik!');
  assert.equal(greet('Shurik', 'toString'), 'Hello, Shurik!');
});
===API===
# Greeting API

The `greet` function builds a localized greeting. It has no dependencies and
uses only Node's standard library.

## Import

```ts
import { greet } from './greet.ts';
```

## Signature

```ts
greet(name = 'world', locale = 'en');
```

- `name` *(string, optional)* — the person or thing to greet. Defaults to
  `'world'`.
- `locale` *(string, optional)* — the language tag for the greeting. Supported
  values are `'en'` (English) and `'es'` (Spanish). Defaults to `'en'`.

Returns the greeting as a `string`. Any unknown or unsupported `locale` falls
back to English, so existing callers that pass only `name` keep working.

## Supported locales

| Locale | Greeting                |
| ------ | ----------------------- |
| `en`   | `Hello, <name>!`        |
| `es`   | `¡Hola, <name>!`        |

## Examples

Default English greeting:

```ts
greet();            // 'Hello, world!'
greet('Shurik');    // 'Hello, Shurik!'
```

Explicit English locale:

```ts
greet('Shurik', 'en'); // 'Hello, Shurik!'
```

Spanish locale:

```ts
greet('Shurik', 'es'); // '¡Hola, Shurik!'
greet('Mundo', 'es');  // '¡Hola, Mundo!'
```

Fallback for an unsupported locale:

```ts
greet('Shurik', 'fr');       // 'Hello, Shurik!'
greet('Shurik', 'unknown');  // 'Hello, Shurik!'
```

## Tests

